"""Translations for the standalone boot-sector repair utility."""


def _translations(*values):
    languages = ("es", "fr", "de", "it", "pt-BR", "bg", "nl", "pl", "ja", "ko", "zh-Hans")
    if len(values) != len(languages):
        raise ValueError("Boot-sector translations must cover every language.")
    return dict(zip(languages, values))


